  <meta name="description" content="Lemon ricotta pancakes for four, ready in 25 minutes. A simple recipe with creamy ricotta and fresh lemon zest.">
  <title>Lemon ricotta pancakes · Sunday table</title>
  <style>
    :root {
      --paper: #faf8f2; --ink: #292d25; --muted: #686a5e; --accent: #a74825;
      --accent-hover: #87391d; --line: #dcded0; --panel: #f0f0e5; --white: #fffdf8;
      --check-border: #858774; --lemon: #edc74b;
      --serif: Georgia, '"'Times New Roman', serif; --sans: Arial, Helvetica, sans-serif;
      --space-1: 4px; --space-2: 8px; --space-3: 12px; --space-4: 16px; --space-6: 24px;
      --space-8: 32px; --space-12: 48px; --space-16: 64px; --space-24: 96px;
    }
    * { box-sizing: border-box; }
    html { scroll-behavior: smooth; scroll-padding-top: 32px; }
    body { margin: 0; background: var(--paper); color: var(--ink); font-family: var(--sans); font-size: 16px; line-height: 1.6; -webkit-font-smoothing: antialiased; }
    a { color: inherit; text-decoration: none; }
    button { font: inherit; cursor: pointer; }
    a, button, input { -webkit-tap-highlight-color: transparent; }
    :focus-visible { outline: 2px solid var(--accent); outline-offset: 5px; }
    .skip-link { position: absolute; left: 16px; top: -80px; padding: 12px 24px; background: var(--white); z-index: 5; }
    .skip-link:focus { top: 16px; }
    .wrap { width: min(1200px, calc(100% - 96px)); margin-inline: auto; }
    .site-header { min-height: 112px; display: flex; align-items: center; justify-content: space-between; border-bottom: 1px solid var(--line); }
    .brand { display: inline-flex; align-items: center; gap: 12px; font-family: var(--serif); font-size: 30px; letter-spacing: -1px; }
    .brand svg { width: 38px; height: 38px; flex-shrink: 0; }
    .site-nav { display: flex; gap: 32px; font-size: 14px; }
    .site-nav a { display: inline-flex; align-items: center; min-height: 44px; border-bottom: 1px solid transparent; }
    .site-nav a:hover { color: var(--accent); border-color: var(--accent); }
    .hero { display: grid; grid-template-columns: 1fr 1fr; gap: 64px; align-items: center; padding-block: 48px 64px; }
    .hero-copy { padding-block: 16px; }
    .category { display: flex; align-items: center; gap: 12px; color: var(--accent); font-size: 11px; font-weight: 600; text-transform: uppercase; letter-spacing: 2px; margin: 0 0 24px; }
    .category span { width: 24px; height: 1px; background: currentColor; }
    h1 { font-family: var(--serif); font-size: clamp(52px, 5.5vw, 76px); line-height: 1.04; font-weight: 400; letter-spacing: -3px; margin: 0 0 24px; }
    h1 span { display: block; }
    .intro { max-width: 370px; color: var(--muted); font-size: 17px; line-height: 1.75; margin: 0 0 32px; }
    .recipe-facts { display: flex; align-items: center; gap: 32px; margin-bottom: 32px; }
    .fact { display: flex; align-items: center; gap: 12px; }
    .fact + .fact { padding-left: 32px; border-left: 1px solid var(--line); }
    .fact svg { width: 23px; height: 23px; color: var(--muted); }
    .fact strong { display: block; font-weight: 500; font-size: 15px; line-height: 1.5; }
    .fact small { display: block; color: var(--muted); font-size: 12px; }
    .actions { display: flex; align-items: center; gap: 24px; flex-wrap: wrap; }
    .primary { min-height: 48px; display: inline-flex; align-items: center; justify-content: center; gap: 24px; padding: 12px 24px; background: var(--accent); color: var(--white); border: 1px solid var(--accent); border-radius: 3px; font-size: 13px; font-weight: 500; transition: background 150ms; }
    .primary:hover { background: var(--accent-hover); border-color: var(--accent-hover); }
    .primary:active { transform: translateY(1px); }
    .primary svg, .print-button svg { width: 16px; height: 16px; }
    .print-button { display: inline-flex; align-items: center; gap: 8px; border: none; background: transparent; color: var(--ink); min-height: 48px; padding: 8px 0; font-size: 13px; }
    .print-button:hover { color: var(--accent); }
    .hero-photo { position: relative; margin: 0; height: 536px; }
    .hero-photo img { display: block; width: 100%; height: 100%; object-fit: cover; object-position: center 60%; border-radius: 3px; }
    .photo-corner { position: absolute; bottom: -19px; left: -20px; width: 94px; height: 94px; color: var(--ink); background: var(--lemon); border: 7px solid var(--paper); border-radius: 50%; display: grid; place-items: center; }
    .photo-corner svg { width: 56px; height: 56px; }
    .recipe { border-top: 1px solid var(--line); padding-block: 48px 64px; display: grid; grid-template-columns: 360px 1fr; gap: 64px; align-items: start; }
    h2 { font-family: var(--serif); font-size: 32px; font-weight: 400; letter-spacing: -0.7px; line-height: 1.2; margin: 0; }
    .ingredients { background: var(--panel); padding: 32px; border-radius: 3px; }
    .section-heading { display: flex; justify-content: space-between; align-items: center; gap: 16px; margin-bottom: 24px; }
    .serves { color: var(--muted); font-size: 12px; white-space: nowrap; }
    .ingredient-list { list-style: none; margin: 0; padding: 0; }
    .ingredient-list li + li { border-top: 1px solid var(--line); }
    .ingredient-list label { min-height: 49px; display: flex; align-items: center; gap: 12px; cursor: pointer; font-size: 14px; }
    .ingredient-list input { appearance: none; -webkit-appearance: none; width: 17px; height: 17px; margin: 0; border: 1px solid var(--check-border); border-radius: 2px; flex: 0 0 17px; display: grid; place-content: center; background: transparent; cursor: pointer; }
    .ingredient-list input::before { content: ''; width: 8px; height: 4px; border-bottom: 1.5px solid var(--white); border-left: 1.5px solid var(--white); transform: rotate(-45deg) scale(0); margin-top: -2px; }
    .ingredient-list input:checked { background: var(--accent); border-color: var(--accent); }
    .ingredient-list input:checked::before { transform: rotate(-45deg) scale(1); }
    .ingredient-list input:checked + span { color: var(--muted); text-decoration: line-through; text-decoration-color: var(--check-border); }
    .ingredient-list label:hover input:not(:checked) { border-color: var(--accent); }
    .ingredient-list b { font-weight: 600; }
    .ingredient-foot { display: flex; align-items: center; justify-content: space-between; min-height: 44px; margin-top: 16px; border-top: 1px solid var(--line); padding-top: 12px; color: var(--muted); font-size: 11px; }
    .reset { background: none; border: 0; padding: 8px 0 8px 16px; min-height: 44px; font-size: 12px; color: var(--accent); text-decoration: underline; }
    .reset[hidden] { display: none; }
    .method { padding-top: 8px; }
    .method > h2 { margin-bottom: 32px; }
    .steps { list-style: none; padding: 0; margin: 0; counter-reset: method; }
    .steps li { position: relative; display: grid; grid-template-columns: 40px 1fr; gap: 16px; padding-bottom: 28px; counter-increment: method; }
    .steps li::before { content: counter(method, decimal-leading-zero); color: var(--accent); font-family: var(--serif); font-size: 24px; line-height: 1.25; }
    .steps li + li { padding-top: 24px; border-top: 1px solid var(--line); }
    h3 { margin: 0 0 8px; font-size: 17px; font-weight: 500; line-height: 1.6; }
    .steps p { margin: 0; color: var(--muted); font-size: 15px; line-height: 1.75; max-width: 57ch; }
    .site-footer { display: flex; align-items: center; justify-content: space-between; padding-block: 24px 32px; border-top: 1px solid var(--line); color: var(--muted); font-size: 12px; }
    .footer-brand { font-family: var(--serif); font-size: 18px; color: var(--ink); }
    .back-top { display: inline-flex; align-items: center; gap: 12px; min-height: 44px; }
    .back-top:hover { color: var(--accent); }
    @media (min-width: 1440px) { .hero { gap: 80px; } }
    @media (max-width: 1000px) { .wrap { width: calc(100% - 64px); } .hero { gap: 32px; } h1 { font-size: 60px; } .hero-photo { height: 500px; } .recipe { grid-template-columns: 310px 1fr; gap: 40px; } .ingredients { padding: 24px; } .recipe-facts { gap: 24px; } .fact + .fact { padding-left: 24px; } }
    @media (max-width: 700px) {
      .wrap { width: calc(100% - 40px); } .site-header { min-height: 88px; } .brand { font-size: 25px; gap: 8px; } .brand svg { width: 30px; height: 30px; } .site-nav { gap: 16px; font-size: 12px; }
      .hero { grid-template-columns: 1fr; gap: 32px; padding-block: 32px 48px; } .hero-copy { padding: 0; } .category { margin-bottom: 16px; font-size: 10px; } h1 { font-size: clamp(52px, 12vw, 72px); letter-spacing: -2px; } h1 span { display: inline; } .intro { max-width: 430px; margin-bottom: 24px; font-size: 16px; } .recipe-facts { margin-bottom: 24px; } .hero-photo { height: 420px; } .photo-corner { width: 80px; height: 80px; left: -8px; bottom: -16px; } .photo-corner svg { width: 48px; height: 48px; }
      .recipe { grid-template-columns: 1fr; gap: 40px; padding-block: 32px 40px; } .ingredients { padding: 24px; } .ingredient-list label { min-height: 48px; font-size: 15px; } .method { padding: 0; } .method > h2 { margin-bottom: 24px; } .steps li { grid-template-columns: 32px 1fr; gap: 12px; } .steps p { font-size: 15px; } .site-footer { padding-bottom: 24px; }
    }
    @media (prefers-reduced-motion: reduce) { html { scroll-behavior: auto; } * { transition: none "'!important; } }
    @media print {
      :root { --paper: #fff; --ink: #000; --muted: #333; --panel: #fff; --line: #ccc; }
      body { font-size: 11pt; } .wrap { width: 100%; } .site-header { min-height: auto; padding-bottom: 16px; } .brand { font-size: 20px; } .brand svg { width: 28px; height: 28px; } .site-nav, .actions, .hero-photo, .site-footer, .ingredient-foot, .skip-link { display: none; }
      .hero { display: block; padding-block: 24px; } .hero-copy { padding: 0; } h1 { font-size: 36pt; letter-spacing: -1px; } h1 span { display: inline; } .category { margin-bottom: 12px; } .intro { max-width: none; margin-bottom: 16px; } .recipe-facts { margin-bottom: 0; } .recipe { grid-template-columns: 1fr 1.6fr; gap: 32px; padding-block: 24px; } .ingredients { padding: 0; } h2 { font-size: 22pt; } .ingredient-list label { min-height: 34px; font-size: 11pt; } .ingredient-list input:checked + span { text-decoration: none; color: var(--ink); } .steps li { padding-bottom: 16px; break-inside: avoid; } .steps li + li { padding-top: 16px; } .steps p { font-size: 11pt; } h3 { font-size: 12pt; }
    }
  </style>
</head>
<body id="top">
  <a class="skip-link" href="#recipe">Skip to recipe</a>
  <div class="wrap">
    <header class="site-header">
      <a class="brand" href="#top" aria-label="Sunday table, back to top">
        <svg viewBox="0 0 44 44" fill="none" aria-hidden="true"><path d="M13 13C18 7 30 8 34 14s-1 17-7 21-14 0-16-5-4-8 2-17Z" fill="#edc74b" stroke="#5a623c" stroke-width="1.3"/><path d="M27 11c0-7 7-9 12-7-2 7-7 10-12 7Z" fill="#5a623c"/><path d="M26 13c1-4 0-6-2-8" stroke="#5a623c" stroke-width="1.3" stroke-linecap="round"/></svg>
        <span>sunday table</span>
      </a>
      <nav class="site-nav" aria-label="Recipe sections"><a href="#ingredients">Ingredients</a><a href="#method">Method</a></nav>
    </header>
    <main>
      <section class="hero" aria-labelledby="recipe-title">
        <div class="hero-copy">
          <p class="category"><span></span> Breakfast &amp; brunch</p>
          <h1 id="recipe-title"><span>Lemon ricotta</span> pancakes</h1>
          <p class="intro">Soft, golden pancakes with creamy ricotta and a little lemon zest.</p>
          <div class="recipe-facts">
            <div class="fact"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.4" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2" stroke-linecap="round" stroke-linejoin="round"/></svg><div><strong>25 minutes</strong><small>Total time</small></div></div>
            <div class="fact"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.4" aria-hidden="true"><circle cx="9" cy="7" r="3"/><path d="M3 20v-2a6 6 0 0 1 12 0v2M16 4a3 3 0 0 1 0 6m2 4a5 5 0 0 1 3 4v2" stroke-linecap="round"/></svg><div><strong>4 people</strong><small>Serves</small></div></div>
          </div>
          <div class="actions">
            <a class="primary" href="#recipe">Jump to recipe <svg viewBox="0 0 20 20" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="M10 3v13m-5-5 5 5 5-5" stroke-linecap="round" stroke-linejoin="round"/></svg></a>
            <button class="print-button" type="button" onclick="window.print()"><svg viewBox="0 0 20 20" fill="none" stroke="currentColor" stroke-width="1.3" aria-hidden="true"><path d="M5 7V3h10v4M5 14H3V7h14v7h-2M5 11h10v6H5z" stroke-linejoin="round"/><path d="M14 9h1"/></svg>Print recipe</button>
          </div>
        </div>
        <figure class="hero-photo">
          <img src="__PANCAKE_IMAGE__" alt="A stack of golden pancakes with syrup being poured over the top" width="1400" height="1692" fetchpriority="high">
          <div class="photo-corner" aria-hidden="true"><svg viewBox="0 0 64 64" fill="none" stroke="currentColor" stroke-width="1.4"><path d="M13 43C11 30 21 17 35 17s22 13 18 23-17 16-27 12-10-7-13-9Z"/><path d="M18 40c-2-10 6-19 16-19s17 9 14 17-12 13-20 10-8-5-10-8ZM33 22l-2 24m-11-18 22 15m-24-7 29-3M35 17c-1-7 5-12 13-11-1 9-7 13-13 11Z" stroke-linecap="round" stroke-linejoin="round"/></svg></div>
        </figure>
      </section>
      <section class="recipe" id="recipe" aria-label="Recipe ingredients and instructions">
        <div class="ingredients" id="ingredients">
          <div class="section-heading"><h2>Ingredients</h2><span class="serves">Serves 4</span></div>
          <ul class="ingredient-list">
            <li><label><input type="checkbox"><span><b>1 cup</b> ricotta</span></label></li>
            <li><label><input type="checkbox"><span><b>¾ cup</b> milk</span></label></li>
            <li><label><input type="checkbox"><span><b>2</b> eggs</span></label></li>
            <li><label><input type="checkbox"><span>Zest of <b>1 lemon</b></span></label></li>
            <li><label><input type="checkbox"><span><b>1 cup</b> flour</span></label></li>
            <li><label><input type="checkbox"><span><b>2 tablespoons</b> sugar</span></label></li>
            <li><label><input type="checkbox"><span><b>1 teaspoon</b> baking powder</span></label></li>
            <li><label><input type="checkbox"><span><b>A pinch</b> of salt</span></label></li>
            <li><label><input type="checkbox"><span>Butter, for the pan</span></label></li>
          </ul>
          <div class="ingredient-foot"><span id="ingredient-progress" aria-live="polite">0 of 9 ingredients ready</span><button class="reset" type="button" hidden>Reset</button></div>
        </div>
        <div class="method" id="method">
          <h2>Let’s make pancakes</h2>
          <ol class="steps">
            <li><div><h3>Whisk the wet ingredients</h3><p>In a bowl, whisk together the ricotta, milk, eggs, and lemon zest.</p></div></li>
            <li><div><h3>Fold in the dry ingredients</h3><p>Add the flour, sugar, baking powder, and salt. Gently fold the dry ingredients into the ricotta mixture.</p></div></li>
            <li><div><h3>Give it a little rest</h3><p>Let the batter rest for 5 minutes.</p></div></li>
            <li><div><h3>Cook, flip, and serve</h3><p>Butter a pan over medium heat. Add the batter and cook until bubbles form on the surface, then flip once to cook the other side.</p></div></li>
          </ol>
        </div>
      </section>
    </main>
    <footer class="site-footer"><span class="footer-brand">sunday table</span><a class="back-top" href="#top">Back to top <span aria-hidden="true">↑</span></a></footer>
  </div>
  <script>
    const ingredients = [...document.querySelectorAll('"'.ingredient-list input')];
    const progress = document.getElementById('ingredient-progress');
    const reset = document.querySelector('.reset');
    function updateIngredients() {
      const count = ingredients.filter(input => input.checked).length;
      progress.textContent = "'`${count} of ${ingredients.length} ingredients ready`;
      reset.hidden = count === 0;
    }
    ingredients.forEach(input => input.addEventListener('"'change', updateIngredients));
    reset.addEventListener('click', () => {
      ingredients.forEach(input => { input.checked = false; });
      updateIngredients();
      ingredients[0].focus();
    });
    updateIngredients();
  </script>
</body>
</html>
EOF
