from pathlib import Path
import base64
page = Path('index.html')
page.write_text(page.read_text().replace('__PANCAKE_IMAGE__', 'data:image/jpeg;base64,' + base64.b64encode(Path('/tmp/pancakes-alt.jpg').read_bytes()).decode()))
PY"

